import{_ as t,o as e,c as o,ae as a}from"./chunks/framework.Dn7Y7LSn.js";const p=JSON.parse('{"title":"Git: Version Control System","description":"","frontmatter":{},"headers":[],"relativePath":"tools/git.md","filePath":"tools/git.md"}'),s={name:"tools/git.md"};function r(n,i,l,c,d,h){return e(),o("div",null,[...i[0]||(i[0]=[a(`<h1 id="git-version-control-system" tabindex="-1">Git: Version Control System <a class="header-anchor" href="#git-version-control-system" aria-label="Permalink to &quot;Git: Version Control System&quot;">​</a></h1><p><strong>Git</strong> এর পূর্ণরূপ Global Information Tracker। এটি আমাদের কোডের বিভিন্ন ভার্সন ম্যানেজ করতে সাহায্য করে।</p><h3 id="basic-configuration" tabindex="-1">Basic Configuration <a class="header-anchor" href="#basic-configuration" aria-label="Permalink to &quot;Basic Configuration&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Your Name&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your@email.com&quot;</span></span></code></pre></div><h3 id="git-workflow" tabindex="-1">Git Workflow <a class="header-anchor" href="#git-workflow" aria-label="Permalink to &quot;Git Workflow&quot;">​</a></h3><ol><li><strong>Working Directory:</strong> যেখানে আমরা কোড লিখছি।</li><li><strong>Staging Area:</strong> যেখানে কোড কমিট করার জন্য তৈরি করা হয় (<code>git add</code>).</li><li><strong>Local Repository:</strong> যেখানে কোড স্থায়ীভাবে সেভ হয় (<code>git commit</code>).</li></ol><h3 id="advanced-git-workflow-live-class-notes" tabindex="-1">Advanced Git Workflow (Live Class Notes) <a class="header-anchor" href="#advanced-git-workflow-live-class-notes" aria-label="Permalink to &quot;Advanced Git Workflow (Live Class Notes)&quot;">​</a></h3><p>কোডের বিভিন্ন ভার্সনে আনডু (undo) করতে হলে আমরা <code>reflog</code>, <code>reset</code>, বা <code>revert</code> ব্যবহার করতে পারি:</p><ul><li><code>git reflog</code>: আগের সমস্ত কমিটের পয়েন্টার (HEAD) দেখতে।</li><li><code>git reset HEAD@{5}</code>: ৫ কমিট আগে ফিরে যাবে তবে কোডগুলো Staging অবস্থায় থাকবে।</li><li><code>git reset HEAD@{5} --hard</code>: হার্ডলি আনডু হবে, অর্থাৎ কোড পার্মানেন্টলি ডিলিট হয়ে আগের অবস্থায় ফিরে যাবে।</li><li><code>git revert &lt;commit-hash&gt;</code>: নির্দিষ্ট কমিটের পরিবর্তনগুলো রিভার্ট (undo) করে নতুন একটি কমিট তৈরি করে (যেমন: <code>git revert 0c4cbfb</code>)।</li></ul><h3 id="branching-and-merging" tabindex="-1">Branching and Merging <a class="header-anchor" href="#branching-and-merging" aria-label="Permalink to &quot;Branching and Merging&quot;">​</a></h3><p>আমরা মূল কোডে পরিবর্তন না এনে নতুন ফিচারের কাজ আলাদা <strong>Branch</strong>-এ করতে পারি।</p><ul><li><code>git branch practice</code>: &quot;practice&quot; নামে নতুন ব্রাঞ্চ তৈরি করতে।</li><li><code>git checkout practice</code>: &quot;practice&quot; ব্রাঞ্চে নেভিগেট করতে। ব্রাঞ্চ তৈরি এবং নেভিগেট একসাথে করতে <code>git checkout -b practice</code> কমান্ড ব্যবহার করা যায়।</li></ul><p><strong>Merging Example:</strong> ধরুন, আমাদের &quot;practice&quot; ব্রাঞ্চে নতুন কিছু কোড রয়েছে এবং &quot;main&quot; ব্রাঞ্চেও আলাদা কিছু কোড আচে। আমরা যদি এগুলো একত্রে করতে চাই, তবে:</p><ol><li>প্রথমে মূল ব্রাঞ্চে যেতে হবে: <code>git checkout main</code></li><li>এরপর মার্জ কমান্ড দিতে হবে: <code>git merge practice</code></li></ol><p><strong>Conflict Resolution:</strong> মার্জ করার সময় কনফ্লিক্ট (conflict) দেখা দিতে পারে (যখন একই ফাইলের একই লাইনে দুই ব্রাঞ্চে পরিবর্তন থাকে)। কনফ্লিক্ট এড়াতে &quot;practice&quot; ব্রাঞ্চে কাজ করার সময় নিয়মিত <code>git pull</code> বা <code>git merge main</code> করে মূল ব্রাঞ্চের আপডেট নিয়ে রাখা উচিত। কনফ্লিক্ট দেখা দিলে সেটা manually সলভ করে তারপর কমিট করতে হয়।</p><p><code>git stash</code>: ফাইলগুলো কমিট করার উপযুক্ত অবস্থায় না থাকলে, টেম্পোরারি (temporary) সেভ করে মূল ব্রাঞ্চে পরিবর্তন করতে আমরা <code>stash</code> ব্যবহার করতে পারি।</p><p>ব্রাঞ্চের কাজ শেষ হয়ে গেলে সেটি ডিলিট করতে:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> practice</span></span></code></pre></div><p>(বি.দ্র: <code>git log</code> দেখার সময় যদি <code>:</code> (কোলন) আসে, তবে নেভিগেট করতে অ্যারো-কী এবং বের হতে <code>q</code> চাপতে হয়।)</p><h3 id="remote-repository-fork-clone" tabindex="-1">Remote Repository, Fork &amp; Clone <a class="header-anchor" href="#remote-repository-fork-clone" aria-label="Permalink to &quot;Remote Repository, Fork &amp; Clone&quot;">​</a></h3><ul><li>গিটহাব রিপোজিটরির Settings &gt; Danger Zone এ গিয়ে এর Visibility (Public / Private) পরিবর্তন করা যায়।</li><li><strong>Clone:</strong> অন্য কারো প্রোজেক্ট ডাউনলোড করে কাজ করতে চাইলে সেটি ক্লোন করতে হয়। যেমন: <code>git clone https://github.com/faisal2410/phpmvc.git</code></li><li><strong>Fork:</strong> ওপেন সোর্স প্রজেক্টে কন্ট্রিবিউট (contribute) করতে চাইলে প্রথমে ওই প্রজেক্ট নিজের প্রোফাইলে Fork করে নিতে হয়। তারপর নিজের ওই ফর্ক করা প্রোজেক্ট ক্লোন করে কাজ করা হয়। কাজ শেষে আসল রিপোজটরিতে <strong>Pull Request</strong> বা PR পাঠাতে হয়।</li></ul><h3 id="cherry-pick" tabindex="-1">Cherry-Pick <a class="header-anchor" href="#cherry-pick" aria-label="Permalink to &quot;Cherry-Pick&quot;">​</a></h3><p>আমাদের কোনো ব্রাঞ্চে যদি অনেকগুলো কমিট থাকে, এবং সেগুলোর মধ্যে নির্দিষ্ট একটি বা দুটি কমিট মূল ব্রাঞ্চে (main) মার্জ করতে চাই, তবে <strong><code>git cherry-pick &lt;commit-hash&gt;</code></strong> কমান্ড ব্যবহার করা হয়।</p><h3 id="github-profile-customization" tabindex="-1">Github Profile customization <a class="header-anchor" href="#github-profile-customization" aria-label="Permalink to &quot;Github Profile customization&quot;">​</a></h3><p>গিটহাব প্রোফাইলকে আরো সুন্দর এবং কাস্টমাইজ করতে চাইলে <code>skyline.github.com/&lt;username&gt;</code> এর মতো থ্রি-ডি ভিউ ব্যবহার করার সুযোগ রয়েছে।</p><p>বিস্তারিত জানতে: <a href="https://git-scm.com/doc" target="_blank" rel="noreferrer">git-scm.com/doc</a></p>`,26)])])}const k=t(s,[["render",r]]);export{p as __pageData,k as default};
